<script setup>
import { showDiagnostics } from '../services/presentation.js'
import { computed,onMounted,ref } from 'vue'
import { router } from '../router.js'
import { state,t,bridge,run,notify } from '../state.js'
import { personal,loadPersonal } from '../personal-state.js'
import { commerceAction } from '../commerce-state.js'
import { useMembership } from '../composables-membership.js'
import { person } from '../social-state.js'
import ContentShell from '../components/ContentShell.vue'
import AppTabBar from '../components/AppTabBar.vue'
import AppModal from '../components/AppModal.vue'
import ActionButton from '../components/ActionButton.vue'
import AppIcon from '../components/AppIcon.vue'
const modal=ref(''),p=computed(()=>state.user?.profile),self=computed(()=>person(state.user?.id)),tools=ref(false)
const {membership,expiry,inactiveKey}=useMembership()
onMounted(async()=>{await loadPersonal();await commerceAction('snapshot',true)})
const entries=[['my-lights','lights','p2.myLights'],['my-posts','posts','p2.myPosts'],['collections','collections','s.collections'],['settings','settings','p5.settings'],['feedback','feedback','p5.feedback']]
</script>
<template><ContentShell class="mine-shell p5-shell" :title="t('mine')" :ready="personal.loaded" :show-error="personal.loaded"><div v-if="!personal.loaded" class="content-state"><p v-if="state.ui.error" class="error-banner" role="alert" :data-error-code="state.ui.error">{{ t('p5.loadFailed') }}</p><p v-else>{{ t('working') }}</p><ActionButton v-if="!state.ui.busy" @click="loadPersonal">{{ t('retry') }}</ActionButton></div><template v-else-if="p"><button class="mine-identity" :aria-label="t('p5.editProfile')" @click="router.push('/edit-profile')"><div class="mine-avatar-wrap"><img class="mine-avatar" :src="p.photos?.[0]?.url||'/images/default-avatar.svg'" alt=""/><img v-if="membership.active" class="mine-avatar-pro" src="/images/p6/pro-badge.svg" alt="PRO"/></div><span><strong>{{ p.displayName||t('notProvided') }}</strong><small class="mine-id"><img src="/images/p5/id-badge.png" alt="ID"/><span>{{ state.user.isTest?'ELV10001':state.user.id }}</span></small><p>{{ p.about||t('s.noAbout') }}</p></span><AppIcon name="arrow" :size="16"/></button><button class="mine-pro" :class="{'mine-pro-active':membership.active}" @click="router.push('/store?from=/mine')"><span><strong>{{ t(membership.active?'p6.proActivated':'p5.upgrade') }}</strong><small>{{ membership.active?t('p6.proValidUntil',{date:expiry}):membership.status!=='none'?t('p6.'+inactiveKey,{date:expiry}):t('p5.upgradeHint') }}</small><small v-if="membership.active&&membership.environment!=='production'">{{ t('p6.'+membership.environment) }}</small></span><img src="/images/p5/pro-emblem.png" alt=""/></button><div class="mine-counts"><button v-for="[key,label] in [['friends','friends'],['following','following'],['followers','followers']]" :key="key" @click="key==='friends'?router.push('/friends?from=/mine'):modal=key"><strong>{{ self?.counts?.[key]||0 }}</strong><span>{{ t('s.'+label) }}</span></button></div><nav class="mine-grid" :aria-label="t('mine')"><button v-for="[path,icon,label] in entries" :key="path" @click="router.push('/'+path)"><img :src="'/images/p5/mine-'+icon+'.png'" alt=""/><span>{{ t(label) }}</span></button></nav><button class="mine-help" @click="router.push('/help?from=/mine')"><img src="/images/p5/mine-help.png" alt=""/><span>{{ t('p5.help') }}</span><AppIcon name="arrow" :size="16"/></button><button v-if="showDiagnostics&&state.user.isTest" class="text-link personal-tools" @click="tools=true">{{ t('p5.checks') }}</button></template><template #tabs><AppTabBar/></template></ContentShell><AppModal v-if="modal" :title="t(modal==='premium'?'p5.upgrade':'s.'+modal)" @close="modal=''"><p v-if="modal==='premium'">{{ t('p5.purchaseUnavailable') }}</p><template v-else><p v-if="!personal.connections[modal]?.length">{{ t('p5.relationshipEmpty') }}</p><button v-for="id in personal.connections[modal]||[]" :key="id" class="option-row" @click="modal='';router.push({name:'profile',params:{id},query:{from:'/mine'}})">{{ person(id)?.displayName||t('notProvided') }}</button></template></AppModal><AppModal v-if="showDiagnostics&&tools" :title="t('p5.checks')" @close="tools=false"><p>{{ t('p5.checksHint') }}</p><div class="source-actions"><button v-for="op in ['snapshot','saveProfile','saveCollection','collectionPosts','deletePost','submitFeedback','savePreferences']" :key="op" class="option-row" @click="run('personal-check',signal=>bridge.call('personal','simulateFailure',{operation:op},{signal})).then(ok=>{if(ok){tools=false;notify('p5.failureArmed')}})">{{ t('p5.fail_'+op) }}</button></div></AppModal></template>
